    from itertools import combinations

    # Function to check if a group of students can work together calmly
    def can_work_together_calmly(group):
        group_algorithms = set()
        for student in group:
            for j in range(60):
                if a[student] & (1 << j):
                    group_algorithms.add(j)
        for student in group:
            for j in range(60):
                if a[student] & (1 << j):
                    if all((a[other] & (1 << j)) == 0 for other in group if other != student):
                        return False
        return True

    max_sum = 0
    # Check all possible groups of at least two students
    for r in range(2, n + 1):
        for group in combinations(range(n), r):
            if can_work_together_calmly(group):
                current_sum = sum(b[i] for i in group)
                max_sum = max(max_sum, current_sum)

    return max_sum

